#include <algorithm>
#include <cstddef>
#include <iostream>
#include <memory>
#include <utility>

struct Node {
  int id = 0;
  std::unique_ptr<Node> left;
  std::unique_ptr<Node> right;
};

[[nodiscard]] std::unique_ptr<Node> node(int id, std::unique_ptr<Node> left = nullptr,
                                         std::unique_ptr<Node> right = nullptr) {
  return std::make_unique<Node>(id, std::move(left), std::move(right));
}

// The height (relay count on the tallest downward path) rooted at n; folds the best chain found
// anywhere in the subtree into `best` on the way back up.
std::ptrdiff_t height(const Node* n, std::ptrdiff_t& best) {
  if (n == nullptr) return 0;
  const std::ptrdiff_t left = height(n->left.get(), best);
  const std::ptrdiff_t right = height(n->right.get(), best);
  best = std::max(best, left + right + 1);
  return std::max(left, right) + 1;
}

[[nodiscard]] std::ptrdiff_t longest_relay_chain(const Node* root) {
  std::ptrdiff_t best = 0;
  height(root, best);
  return best;
}

int main() {
  std::cout << "empty: " << longest_relay_chain(nullptr) << '\n';
  std::cout << "single: " << longest_relay_chain(node(1).get()) << '\n';

  const auto chain = node(1, nullptr, node(2, nullptr, node(3, nullptr, node(4))));
  std::cout << "chain of 4: " << longest_relay_chain(chain.get()) << '\n';

  // The longest chain passes through relay 1 but not through the root, 5.
  const auto off_root = node(5, node(1, node(2), node(3, nullptr, node(4))), nullptr);
  std::cout << "off root: " << longest_relay_chain(off_root.get()) << '\n';

  const auto balanced = node(1, node(2, node(4), node(5)), node(3, node(6), node(7)));
  std::cout << "balanced 7: " << longest_relay_chain(balanced.get()) << '\n';
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <optional>
#include <queue>
#include <string>
#include <vector>

struct Hop {
  std::ptrdiff_t a = 0;
  std::ptrdiff_t b = 0;
  std::int64_t roughness = 0;
};

// True when start can reach goal using only hops with roughness at most limit.
[[nodiscard]] bool reachable_within(std::ptrdiff_t n, const std::vector<Hop>& hops, std::ptrdiff_t start,
                                    std::ptrdiff_t goal, std::int64_t limit) {
  std::vector<std::vector<std::ptrdiff_t>> neighbours(static_cast<std::size_t>(n));
  for (const Hop& hop : hops) {
    if (hop.roughness > limit) continue;
    neighbours[static_cast<std::size_t>(hop.a)].push_back(hop.b);
    neighbours[static_cast<std::size_t>(hop.b)].push_back(hop.a);
  }
  std::vector<bool> seen(static_cast<std::size_t>(n), false);
  std::queue<std::ptrdiff_t> pending;
  seen[static_cast<std::size_t>(start)] = true;
  pending.push(start);
  while (!pending.empty()) {
    const std::ptrdiff_t v = pending.front();
    pending.pop();
    if (v == goal) return true;
    for (const std::ptrdiff_t u : neighbours[static_cast<std::size_t>(v)]) {
      if (!seen[static_cast<std::size_t>(u)]) {
        seen[static_cast<std::size_t>(u)] = true;
        pending.push(u);
      }
    }
  }
  return start == goal;
}

// The smallest R such that start can reach goal using only hops with roughness at most R, or no
// value when even every hop together cannot connect them.
[[nodiscard]] std::optional<std::int64_t> smallest_max_roughness(std::ptrdiff_t n, const std::vector<Hop>& hops,
                                                                  std::ptrdiff_t start, std::ptrdiff_t goal) {
  if (start == goal) return 0;
  std::vector<std::int64_t> candidates;
  candidates.reserve(hops.size());
  for (const Hop& hop : hops) candidates.push_back(hop.roughness);
  std::ranges::sort(candidates);
  candidates.erase(std::ranges::unique(candidates).begin(), candidates.end());

  const auto point = std::ranges::partition_point(
      candidates, [&](std::int64_t limit) { return !reachable_within(n, hops, start, goal, limit); });
  if (point == candidates.end()) return std::nullopt;
  return *point;
}

[[nodiscard]] std::string text(std::optional<std::int64_t> value) {
  return value ? std::format("{}", *value) : "none";
}

int main() {
  const std::vector<Hop> hops{{0, 1, 5}, {1, 2, 9}, {0, 2, 7}, {2, 3, 2}};
  std::cout << "0 to 3: " << text(smallest_max_roughness(4, hops, 0, 3)) << '\n';
  std::cout << "0 to 0: " << text(smallest_max_roughness(4, hops, 0, 0)) << '\n';
  std::cout << "1 to 3: " << text(smallest_max_roughness(4, hops, 1, 3)) << '\n';
  std::cout << "0 to 4, unreachable: " << text(smallest_max_roughness(5, hops, 0, 4)) << '\n';
  std::cout << "direct hop: " << text(smallest_max_roughness(2, {{0, 1, 3}}, 0, 1)) << '\n';
  const std::vector<Hop> flat{{0, 1, 4}, {1, 2, 4}, {2, 3, 4}};
  std::cout << "flat roughness: " << text(smallest_max_roughness(4, flat, 0, 3)) << '\n';
}
